<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Staff;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class StaffStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\StaffModel',
  1 => 'App\\Controllers\\StaffController',
  2 => 'App\\Validation\\StaffRules',
  3 => 'App\\Entities\\StaffEntity',
  4 => 'App\\Services\\StaffService',
  5 => 'App\\Controllers\\Api\\V1\\StaffApiController',
  6 => 'App\\API\\Resources\\StaffResource',
  7 => 'App\\Validation\\StaffApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
